// GitHub signe en HMAC-SHA256, header `X-Hub-Signature-256: sha256=<hex>`
// (préfixe différent du header Linear `Linear-Signature`, cf. linear-inbound.json).
const crypto = require('crypto');
const secret = $env.GITHUB_WEBHOOK_SECRET;
if (!secret) throw new Error('GITHUB_WEBHOOK_SECRET manquant');

const item = $input.first();
const rawBodyBase64 = item.binary && item.binary.data && item.binary.data.data;
if (!rawBodyBase64) throw new Error('Corps brut introuvable — activer Raw Body sur le Webhook.');

const rawBody = Buffer.from(rawBodyBase64, 'base64');
const header = ((item.json.headers && item.json.headers['x-hub-signature-256']) || '').toString();
const signatureHeader = header.replace(/^sha256=/, '');
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

const expectedBuf = Buffer.from(expected, 'utf8');
const receivedBuf = Buffer.from(signatureHeader, 'utf8');
const valid = expectedBuf.length === receivedBuf.length && crypto.timingSafeEqual(expectedBuf, receivedBuf);
if (!valid) throw new Error('Signature GitHub invalide — requête rejetée');

const payload = JSON.parse(rawBody.toString('utf8'));
if (payload.action !== 'closed') return []; // on ne s'intéresse qu'à la fermeture (merge ou non)

return [{ json: payload }];

// Convention git-conventions.md : "Closes RALPH-42" dans le corps de la PR.
const pr = $json.pull_request;
const body = pr.body || '';
const match = body.match(/Closes\s+([A-Z]+-\d+)/i);
if (!match) {
  throw new Error('Aucun "Closes <IDENTIFIER>" trouvé dans le corps de la PR — impossible de relier un ticket Linear, abandon.');
}

return [{
  json: {
    ticketIdentifier: match[1].toUpperCase(),
    merged: !!pr.merged,
    additions: pr.additions,
    deletions: pr.deletions,
    changedFiles: pr.changed_files,
    prUrl: pr.html_url,
    headSha: pr.head.sha
  }
}];

const extracted = $('Extraire ticket_identifier').first().json;
const ticketResp = $('Linear: récupérer ticket + labels').first().json;
const resolvedResp = $('Linear: resolve states + labels (équipe)').first().json;

const ticket = ticketResp.data && ticketResp.data.issue;
if (!ticket) {
  throw new Error(`Ticket Linear ${extracted.ticketIdentifier} introuvable.`);
}

const states = (resolvedResp.data && resolvedResp.data.team && resolvedResp.data.team.states.nodes) || [];
const labels = (resolvedResp.data && resolvedResp.data.team && resolvedResp.data.team.labels.nodes) || [];
const labelsByName = Object.fromEntries(labels.map((l) => [l.name, l.id]));

const ticketLabelNames = (ticket.labels.nodes || []).map((l) => l.name);
const attemptLabel = ticketLabelNames.find((n) => /^attempt:\d+$/.test(n));
const attempt = attemptLabel ? parseInt(attemptLabel.split(':')[1], 10) : 1;
const alreadyRejectedOnce = ticketLabelNames.includes('rejected:1');

const stateByName = Object.fromEntries(states.map((s) => [s.name, s.id]));

return [{
  json: {
    ...extracted,
    ticketId: ticket.id,
    attempt,
    alreadyRejectedOnce,
    labelsByName,
    stateByName
  }
}];

const ctx = $('Construire contexte').first().json;
const checkRuns = ($('GitHub: check-runs (statut CI final)').first().json.check_runs) || [];
const ciFailed = checkRuns.some((r) => r.status === 'completed' && !['success', 'neutral', 'skipped'].includes(r.conclusion));
const ciStatus = checkRuns.length === 0 ? 'aucun check trouvé' : (ciFailed ? 'échec (mergé malgré tout — vérifier)' : 'vert');

const spendResp = $('LiteLLM: key info agent-dev').first().json;
const spend = (spendResp.info && spendResp.info.spend) || 0;

const body = [
  '✅ Mergé — preuve de travail Symphony',
  '',
  `PR : ${ctx.prUrl}`,
  `CI : ${ciStatus} (à la date de ce commentaire, ${new Date().toISOString()})`,
  `Diff : +${ctx.additions} / -${ctx.deletions} sur ${ctx.changedFiles} fichier(s)`,
  `Coût du run (clé LiteLLM agent-dev, cumulé) : $${spend.toFixed(2)}`,
  `Essais d'auto-correction consommés : ${ctx.attempt}/3`
].join('\n');

return [{ json: { ...ctx, body } }];
